class Solution {
public:
    int kInversePairs(int n, int k) {
        const int MOD = 1000000007;
        vector<int> prev(k + 1, 0), cur(k + 1, 0);
        prev[0] = 1;
        for (int i = 2; i <= n; i++) {
            cur[0] = 1;
            for (int j = 1; j <= k; j++) {
                long long val = (long long)cur[j - 1] + prev[j];
                if (j >= i) val -= prev[j - i];
                val %= MOD;
                if (val < 0) val += MOD;
                cur[j] = (int)val;
            }
            swap(prev, cur);
        }
        return prev[k];
    }
};
